 if(a==='apply-move-sheet'){const dest=+dialog.querySelector('[data-destination]').value,copy=dialog.querySelector('[data-copy-sheet]').checked;change(()=>moveSheet(book,book.active,dest,copy));return true;}
 if(a==='tab-color'){taskPanel('Color de pestaña','<label>Color<input type="color" data-tab-color value="'+(sheet().tabColor||'#21834c')+'"></label>'+button('apply-tab-color','Aplicar color','fill'));return true;}
 if(a==='apply-tab-color'){const color=dialog.querySelector('[data-tab-color]').value;change(()=>sheet().tabColor=color);return true;}
 if(a==='default-width'){taskPanel('Ancho predeterminado','<label>Ancho en píxeles<input type="number" min="40" max="500" data-default-width value="'+(sheet().defaultWidth||112)+'"></label>'+button('apply-default-width','Aplicar','grid'));return true;}
 if(a==='apply-default-width'){const width=+dialog.querySelector('[data-default-width]').value;change(()=>{writable(sheet());if(!Number.isFinite(width)||width<40||width>500)throw Error('El ancho debe estar entre 40 y 500 píxeles.');sheet().defaultWidth=width;});return true;}
 if(['hide-rows','show-rows','hide-columns','show-columns'].includes(a)){change(()=>{writable(sheet());if(sheet().merges?.length)throw Error('Separa las celdas combinadas antes de ocultar filas o columnas.');const rows=a.endsWith('rows'),key=rows?'hiddenRows':'hiddenColumns';sheet()[key]=a.startsWith('show')?[]:[...new Set([...(sheet()[key]||[]),...selection().map(position).map(p=>p[rows?0:1])])];if(sheet()[key].length===(rows?ROWS:COLS))throw Error('Debe quedar al menos una fila o columna visible.');});return true;}
 if(a==='toggle-lock'){format('locked',current().locked===false);return true;}
 if(a==='autofit-height'){change(()=>{writable(sheet());sheet().rowHeights||={};const canvas=document.createElement('canvas'),ctx=canvas.getContext('2d');for(const r of new Set(selection().map(position).map(p=>p[0]))){let height=27;for(let c=0;c<COLS;c++){const cell=sheet().cells[address(r,c)]||{},text=display(sheet(),address(r,c));ctx.font=(cell.size||11)+'pt '+(cell.font||'Arial');const width=(sheet().columnWidths?.[c]||sheet().defaultWidth||112)-12,lines=text.split('\n').reduce((n,t)=>n+(cell.wrap?Math.max(1,Math.ceil(ctx.measureText(t).width/width)):1),0);height=Math.max(height,lines*(cell.size||11)*1.65+8);}sheet().rowHeights[r]=Math.min(300,height);}});return true;}
 if(a==='style-gallery'){taskPanel('Estilos de celda','<p>Selecciona un estilo para '+esc(start===end?start:start+':'+end)+'.</p><div class="sx-all-styles">'+Object.entries(CELL_STYLES).map(([id,s])=>'<button data-sx="preset-'+id+'" style="background:'+ (s.fill||'#fff')+';color:'+(s.color||'#203d31')+';font-weight:'+(s.bold?'bold':'normal')+'">'+s.name+'</button>').join('')+'</div>'+button('save-style','Guardar selección como estilo','save')+(book.styles||[]).map((s,i)=>button('custom-style-'+i,esc(s.name),'brush')).join(''));return true;}
 if(a.startsWith('preset-')||a.startsWith('custom-style-')){const style=a.startsWith('preset-')?CELL_STYLES[a.slice(7)]:book.styles?.[+a.slice(13)];if(style)change(()=>{writable(sheet());for(const ref of selection())sheet().cells[ref]=overrideThemeFormat(sheet().cells[ref],cellFormat(style));});return true;}
