 const draft={format:'general',decimals:2,currency:'COP',locale:'es-CO',useGrouping:true,negativeStyle:'minus',timeType:'hms',fractionType:'2',customCode:'0',font:'Arial',size:11,color:'#203d31',fill:'#ffffff',align:'left',valign:'bottom',border:'none',locked:true,...cellFormat(current())};const touched=new Set();let active=initialTab,borderTouched=false;const modal=document.createElement('dialog');modal.className='sx-cell-dialog';modal.setAttribute('aria-label','Formato de celdas');dialog.append(modal);
 const select=(key,items)=>'<select data-draft="'+key+'">'+items.map(item=>{const [v,n]=Array.isArray(item)?item:[item,item];return '<option value="'+v+'" '+(draft[key]===v||key==='border'&&typeof draft.border==='object'&&v==='custom'?'selected':'')+'>'+n+'</option>';}).join('')+'</select>';
