 if(['number','currency'].includes(f))body+='<label>Números negativos'+select('negativeStyle',[['minus','-1234,10'],['red','1234,10 en rojo'],['red-minus','-1234,10 en rojo'],['paren','(1234,10)'],['red-paren','(1234,10) en rojo']])+'</label>';
