 if(a==='remove-cell-object'){change(()=>{writable(sheet());for(const ref of selection()){const cell=sheet().cells[ref];if(cell)for(const key of ['chart','image','alt','shape','shapeColor'])delete cell[key];}});return true;}

 if(a==='insert-chart'){const target=dialog.querySelector('[data-chart-target]').value.trim().toUpperCase(),type=dialog.querySelector('[data-chart-type]').value,source=start+':'+end;change(()=>{writable(sheet());position(target);if(sheet().cells[target]?.raw||sheet().cells[target]?.chart||sheet().cells[target]?.image||sheet().cells[target]?.shape)throw Error('La celda de destino contiene datos u objetos.');if(mergedAnchor(target)!==target)throw Error('Elige una celda sin combinar.');sheet().cells[target]={...sheet().cells[target],chart:{range:source,type}};sheet().rowHeights||={};sheet().columnWidths||={};const [r,c]=position(target);sheet().rowHeights[r]=180;sheet().columnWidths[c]=280;});return true;}
