 if(a==='apply-pivot'){const group=+dialog.querySelector('[data-pivot-group]').value,col=+dialog.querySelector('[data-pivot-value]').value,op=dialog.querySelector('[data-pivot-op]').value;change(()=>{const rows=pivotSummary(sheet(),start+':'+end,group,col,op),s=newSheet('Resumen '+(book.sheets.length+1));rows.forEach((row,r)=>row.forEach((raw,c)=>s.cells[address(r,c)]={raw:String(raw),bold:r===0,fill:r===0?'#dcf0e1':'#ffffff'}));book.sheets.push(s);book.active=book.sheets.length-1;});return true;}
