 if(a==='apply-shape'){const shape=dialog.querySelector('[data-shape]').value,color=dialog.querySelector('[data-shape-color]').value;change(()=>{writable(sheet());sheet().cells[start]={...current(),shape,shapeColor:color};sheet().rowHeights||={};sheet().rowHeights[position(start)[0]]=80;});return true;}
 if(a==='cell-link'){taskPanel('Vínculo','<label>Destino<input data-cell-link value="'+esc(current().link||'https://')+'"></label><p>Web: https://… · Correo: mailto:nombre@dominio.com · Celda de esta hoja: #B5.</p>'+button('apply-cell-link','Aplicar vínculo','eye')+button('clear-links','Quitar vínculo','eraser'));return true;}
 if(a==='apply-cell-link'){try{format('link',normalizeSheetLink(dialog.querySelector('[data-cell-link]').value));}catch(error){notice(error.message);}return true;}
 if(a==='symbols'){taskPanel('Símbolos','<label>Buscar<input data-sheet-symbol-search placeholder="Grado, flecha, U+03A9…"></label><label>Categoría<select data-sheet-symbol-category><option>Todos</option>'+symbolGroups.map(g=>'<option>'+esc(g[0])+'</option>').join('')+'</select></label><div class="sx-sheet-symbol-grid"></div>');renderSheetSymbols();return true;}
 return false;
