const SHEET_SHAPES={
 rectangle:['Rectángulo','<rect x="5" y="5" width="90" height="50"/>'],rounded:['Rectángulo redondeado','<rect x="5" y="5" width="90" height="50" rx="12"/>'],
 circle:['Elipse','<ellipse cx="50" cy="30" rx="43" ry="25"/>'],diamond:['Rombo','<path d="M50 3 97 30 50 57 3 30Z"/>'],arrow:['Flecha derecha','<path d="M5 20H65V5L95 30 65 55V40H5Z"/>'],
 left:['Flecha izquierda','<path d="M95 20H35V5L5 30 35 55V40H95Z"/>'],triangle:['Triángulo','<path d="M50 3 97 57H3Z"/>'],hexagon:['Hexágono','<path d="M25 3H75L97 30 75 57H25L3 30Z"/>'],
 pentagon:['Pentágono','<path d="M50 3 97 23 79 57H21L3 23Z"/>'],star:['Estrella','<path d="M50 2 62 21 96 22 72 36 80 58 50 45 20 58 28 36 4 22 38 21Z"/>'],
 parallelogram:['Paralelogramo','<path d="M22 5H95L78 55H5Z"/>'],trapezoid:['Trapecio','<path d="M25 5H75L95 55H5Z"/>'],plus:['Cruz','<path d="M38 3H62V20H95V40H62V57H38V40H5V20H38Z"/>'],callout:['Llamada','<path d="M5 5H95V43H40L22 58V43H5Z"/>']};
function sparkGraphic(chart){let points;try{points=range(chart.range).map(ref=>({ref,v:value(sheet(),ref)}));}catch{return '';}
 const nums=points.filter(p=>typeof p.v==='number'&&Number.isFinite(p.v));if(!nums.length)return '<small>Sin datos numéricos</small>';const low=Math.min(0,...nums.map(p=>p.v)),high=Math.max(0,...nums.map(p=>p.v)),span=high-low||1,y=v=>34-(v-low)/span*28,step=100/points.length,color=/^#[0-9a-f]{6}$/i.test(chart.color)?chart.color:'#21804a';let content='';
 if(chart.type==='line'){let segment=[];const flush=()=>{if(segment.length)content+='<polyline fill="none" stroke="'+color+'" stroke-width="2" points="'+segment.join(' ')+'"/>';segment=[];};points.forEach((p,i)=>{if(typeof p.v!=='number'){flush();return;}const x=5+step*(i+.5);segment.push(x+','+y(p.v));content+='<circle cx="'+x+'" cy="'+y(p.v)+'" r="1.7" fill="'+color+'"><title>'+p.ref+': '+p.v+'</title></circle>';});flush();}
 else{const base=chart.type==='win'?20:y(0);content+='<path d="M5 '+base+'H105" stroke="#aebdb3"/>';points.forEach((p,i)=>{if(typeof p.v!=='number'||p.v===0)return;const top=chart.type==='win'?(p.v>0?6:20):Math.min(y(p.v),base),height=chart.type==='win'?14:Math.abs(y(p.v)-base);content+='<rect x="'+(5+i*step+step*.1)+'" y="'+top+'" width="'+(step*.8)+'" height="'+height+'" fill="'+(p.v<0?'#c44343':color)+'"><title>'+p.ref+': '+p.v+'</title></rect>';});}
 return '<svg class="sx-sparkline" viewBox="0 0 110 40" role="img" aria-label="Minigráfico '+esc(chart.range)+'">'+content+'</svg>';}
function cellDecoration(cell){
 let html='';
 if(cell.chart)html+=linkedChart(cell.chart);
 if(cell.image&&/^data:image\/(png|jpeg|webp);base64,/i.test(cell.image))html+='<img class="sx-cell-image" src="'+esc(cell.image)+'" alt="'+esc(cell.alt||'')+'">';
 if(cell.shape)html+='<svg class="sx-cell-shape" viewBox="0 0 100 60" role="img" aria-label="'+esc(SHEET_SHAPES[cell.shape]?.[0]||cell.shape)+'" style="fill:'+esc(cell.shapeColor||'#25824f')+'">'+(SHEET_SHAPES[cell.shape]?.[1]||'')+'</svg>';
 if(cell.link){
  if(cell.link==='#¡REF!')html+='<span class="sx-cell-link" title="El destino del vínculo fue eliminado">!</span>';
  else try{const link=normalizeSheetLink(cell.link);html+=link.startsWith('#')?'<a href="'+esc(link)+'" data-sheet-link="'+esc(link.slice(1))+'" class="sx-cell-link" aria-label="Ir a '+esc(link.slice(1))+'">↗</a>':'<a href="'+esc(link)+'" target="_blank" rel="noopener" class="sx-cell-link" aria-label="Abrir vínculo">↗</a>';}catch{}
 }
 return html;
}

function linkedChart(chart){if(chart.compact)return sparkGraphic(chart);let values;try{values=range(chart.range).map(ref=>({ref,v:value(sheet(),ref)})).filter(p=>typeof p.v==='number').slice(0,30);}catch{return '';}
 if(!values.length)return '<small>Sin datos numéricos</small>';const lo=Math.min(0,...values.map(p=>p.v)),hi=Math.max(0,...values.map(p=>p.v)),span=hi-lo||1,y=v=>130-(v-lo)/span*110,step=240/values.length;let content='<path d="M30 '+y(0)+'H280" stroke="#b4cbbb"/>';
 if(chart.type==='line')content+='<polyline fill="none" stroke="#21804a" stroke-width="2" points="'+values.map((p,i)=>(30+step*(i+.5))+','+y(p.v)).join(' ')+'"/>';
 else content+=values.map((p,i)=>'<rect x="'+(30+step*i+2)+'" y="'+Math.min(y(p.v),y(0))+'" width="'+Math.max(1,step-4)+'" height="'+Math.max(1,Math.abs(y(p.v)-y(0)))+'" fill="'+(p.v<0?'#b95849':'#278653')+'"><title>'+p.ref+': '+p.v+'</title></rect>').join('');
 content+='<text x="4" y="20" font-size="9">'+esc(hi)+'</text><text x="4" y="132" font-size="9">'+esc(lo)+'</text><text x="30" y="150" font-size="10">'+esc(chart.range)+'</text>';return '<svg class="sx-linked-chart" viewBox="0 0 300 160" role="img" aria-label="Gráfico '+esc(chart.range)+'">'+content+'</svg>';}
let borderPen={color:'#203d31',style:'solid',width:1},borderMode=null,borderStroke=null;
const borderOptions=()=>'<label>Color de línea<input data-border-color type="color" value="'+borderPen.color+'"></label><label>Estilo de línea<select data-border-style>'+[['solid','Continua'],['dashed','Discontinua'],['dotted','Punteada'],['double','Doble']].map(([v,n])=>'<option value="'+v+'" '+(borderPen.style===v?'selected':'')+'>'+n+'</option>').join('')+'</select></label><label>Grosor<select data-border-width>'+[1,2,3].map(n=>'<option value="'+n+'" '+(borderPen.width===n?'selected':'')+'>'+n+' px</option>').join('')+'</select></label>';
function borderIcon(preset){const lines={bottom:'M3 19H21',top:'M3 5H21',left:'M4 4V20',right:'M20 4V20',all:'M3 3H21V21H3ZM3 12H21M12 3V21',outside:'M3 3H21V21H3Z',none:'',double:'M3 17H21M3 20H21','thick-outside':'M3 3H21V21H3Z','thick-bottom':'M3 19H21','top-bottom':'M3 4H21M3 20H21','top-thick-bottom':'M3 4H21M3 19H21','top-double-bottom':'M3 4H21M3 17H21M3 20H21'};return '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M3 3H21V21H3ZM3 12H21M12 3V21" stroke="#b2beb7" stroke-dasharray="1 2"/><path d="'+lines[preset]+'" stroke="currentColor" stroke-width="'+(preset.includes('thick')?3:1.4)+'"/></svg>';}
function openBorderMenu(){dialog.querySelector('.sx-border-menu')?.remove();const menu=document.createElement('div');menu.className='sx-border-menu';menu.setAttribute('popover','auto');menu.setAttribute('aria-label','Bordes');menu.innerHTML='<h4>Bordes</h4>'+BORDER_PRESETS.map(([id,label])=>'<button type="button" data-border-preset="'+id+'">'+borderIcon(id)+'<span>'+label+'</span></button>').join('')+'<h4>Dibujar bordes</h4>'+[['draw','Dibujar borde'],['grid','Dibujar cuadrícula de borde'],['erase','Borrar borde']].map(([id,n])=>'<button type="button" data-border-mode="'+id+'">'+icon(id==='erase'?'eraser':'grid')+n+'</button>').join('')+borderOptions()+'<button type="button" data-border-more>Más bordes…</button>';dialog.append(menu);const rect=dialog.querySelector('[data-sx=cell-border]').getBoundingClientRect();menu.style.left=Math.min(rect.left,innerWidth-310)+'px';menu.style.top=Math.min(rect.bottom,innerHeight-300)+'px';menu.style.maxHeight=(innerHeight-parseFloat(menu.style.top)-12)+'px';menu.showPopover();menu.querySelector('button').focus();menu.addEventListener('click',e=>{const preset=e.target.closest('[data-border-preset]'),mode=e.target.closest('[data-border-mode]');if(preset){borderMode=null;delete dialog.querySelector('.sx-grid-scroll').dataset.borderMode;change(()=>applyBorders(sheet(),start+':'+end,preset.dataset.borderPreset,borderPen));menu.hidePopover();}if(mode){borderMode=mode.dataset.borderMode;dialog.querySelector('.sx-grid-scroll').dataset.borderMode=borderMode;notice('Modo '+mode.textContent+'. Arrastra sobre las celdas. Pulsa Esc para terminar.');menu.hidePopover();}if(e.target.closest('[data-border-more]')){menu.hidePopover();openMoreBorders();}});menu.addEventListener('keydown',e=>{if(!['ArrowDown','ArrowUp'].includes(e.key)||e.target.matches('input,select'))return;e.preventDefault();const items=[...menu.querySelectorAll('button')],i=items.indexOf(document.activeElement);items[(i+(e.key==='ArrowDown'?1:-1)+items.length)%items.length].focus();});}
function openMoreBorders(){taskPanel('Más bordes',borderOptions()+'<p>Vista previa de un rango de 2 × 2. Los bordes externos se aplican al contorno de la selección.</p><label>Distribución<select data-border-layout>'+BORDER_PRESETS.map(([id,n])=>'<option value="'+id+'">'+n+'</option>').join('')+'</select></label><div data-border-preview></div><button type="button" data-border-apply>Aplicar bordes a '+esc(start===end?start:start+':'+end)+'</button>');previewBorders();}
