dialog.addEventListener('change',e=>{if(e.target.matches('[data-border-color]'))borderPen.color=e.target.value;if(e.target.matches('[data-border-style]'))borderPen.style=e.target.value;if(e.target.matches('[data-border-width]'))borderPen.width=+e.target.value;if(e.target.matches('[data-border-color],[data-border-style],[data-border-width],[data-border-layout]'))previewBorders();});
