 if(a==='apply-other-sheets'){const targets=[...dialog.querySelectorAll('[data-fill-sheet]:checked')].map(n=>+n.dataset.fillSheet);change(()=>{if(!targets.length)throw Error('Selecciona una hoja de destino.');for(const i of targets)transferCells(sheet(),book.sheets[i],start+':'+end,range(start+':'+end)[0]);});return true;}
 if(a==='flash-fill'){taskPanel('Relleno por ejemplo','<p>Selecciona dos columnas: origen a la izquierda y resultado a la derecha. Escribe un ejemplo en la primera fila de resultado. Se admite extraer una palabra o convertir a mayúsculas/minúsculas; se preservan resultados ya escritos.</p>'+button('apply-flash-fill','Completar resultados vacíos','fill'));return true;}
 if(a==='apply-flash-fill'){change(()=>{const coords=selection().map(position),rs=[...new Set(coords.map(p=>p[0]))],cs=[...new Set(coords.map(p=>p[1]))];if(cs.length!==2)throw Error('Selecciona exactamente dos columnas.');const source=String(value(sheet(),address(rs[0],cs[0]))),example=String(value(sheet(),address(rs[0],cs[1])));if(!source||!example)throw Error('Escribe origen y ejemplo en la primera fila.');const words=source.trim().split(/\s+/),index=words.indexOf(example),mode=example===source.toUpperCase()&&example!==source?'upper':example===source.toLowerCase()&&example!==source?'lower':index>=0&&words.filter(x=>x===example).length===1?'word':null;if(!mode)throw Error('El ejemplo no determina un patrón único de palabra o mayúsculas/minúsculas.');const changes={};for(const r of rs.slice(1)){const target=address(r,cs[1]);if(sheet().cells[target]?.raw)continue;const text=String(value(sheet(),address(r,cs[0])));if(!text)continue;const result=mode==='upper'?text.toUpperCase():mode==='lower'?text.toLowerCase():text.trim().split(/\s+/)[index];if(result===undefined)throw Error('La fila '+(r+1)+' no tiene la palabra esperada.');changes[target]="'"+result;}writeCells(sheet(),changes);});return true;}
 if(a==='justify-text'){taskPanel('Justificar texto en filas','<p>Distribuye las palabras de una columna seleccionada en las filas del mismo rango. No modifica celdas fuera del rango.</p><label>Caracteres por fila<input type="number" data-justify-width min="5" max="200" value="40"></label>'+button('apply-justify','Distribuir texto','align'));return true;}
 if(a==='apply-justify'){const width=+dialog.querySelector('[data-justify-width]').value;change(()=>{const refs=selection();if(new Set(refs.map(r=>position(r)[1])).size!==1||!Number.isInteger(width)||width<5||width>200)throw Error('Selecciona una columna y un ancho de 5 a 200 caracteres.');if(refs.some(r=>typeof value(sheet(),r)==='number'||String(sheet().cells[r]?.raw||'').startsWith('=')))throw Error('Justificar requiere texto sin números ni fórmulas.');const words=refs.map(r=>value(sheet(),r)).join(' ').trim().split(/\s+/),lines=[''];for(const word of words){if(word.length>width)throw Error('Una palabra excede el ancho elegido.');if(lines.at(-1)&&lines.at(-1).length+word.length+1>width)lines.push('');lines[lines.length-1]+=(lines.at(-1)?' ':'')+word;}if(lines.length>refs.length)throw Error('Selecciona más filas: el texto no cabe sin sobrescribir fuera del rango.');writeCells(sheet(),Object.fromEntries(refs.map((r,i)=>[r,lines[i]?"'"+lines[i]:''])));});return true;}
