function barBackground(bar){const color=bar.negative?'#d98479':bar.color||'#77b3d5';return bar.gradient?'linear-gradient(90deg,'+color+',transparent)':color;}
function tableFilterButton(ref){const [r,c]=position(ref),table=[...(sheet().tables||[]),...(sheet().autoFilter?[{id:'auto',range:sheet().autoFilter}]:[])].find(t=>{const refs=range(t.range);return position(refs[0])[0]===r&&refs.includes(ref);});return table?'<button class="sx-table-filter" data-table-filter="'+esc(table.id)+'" data-filter-col="'+c+'" aria-label="Filtrar columna '+address(0,c).slice(0,-1)+'">'+(book.xlsxImport?'<svg viewBox="0 0 12 12" aria-hidden="true"><path d="M1 3h10M3 6h6M5 9h2"/></svg>':'▾')+'</button>':'';}
function openColumnFilter(table,column){dataController.openFilter(table?.range||sheet().autoFilter||selection()[0]+':'+selection().at(-1),column);}
dialog.addEventListener('click',e=>{const t=e.target.closest('[data-table-filter]');if(t)openColumnFilter((sheet().tables||[]).find(x=>x.id===t.dataset.tableFilter),+t.dataset.filterCol);});

function cellBackground(cell){const layers=[];if(cell.diagonalUp)layers.push('linear-gradient(to top right,transparent calc(50% - .5px),#203d31 50%,transparent calc(50% + .5px))');if(cell.diagonalDown)layers.push('linear-gradient(to bottom right,transparent calc(50% - .5px),#203d31 50%,transparent calc(50% + .5px))');const patterns={horizontal:'repeating-linear-gradient(0deg,transparent 0 5px,#203d3125 5px 6px)',vertical:'repeating-linear-gradient(90deg,transparent 0 5px,#203d3125 5px 6px)',diagonal:'repeating-linear-gradient(45deg,transparent 0 5px,#203d3125 5px 6px)',dots:'radial-gradient(#203d3140 1px,transparent 1px)'};if(patterns[cell.pattern])layers.push(patterns[cell.pattern]);return layers.join(',')||'none';}

function conditionVisualOptions(rule){const options=(key,items)=>'<label>'+({palette:'Paleta de escala',iconSet:'Iconos',barFill:'Relleno de barras'}[key])+'<select data-cf="'+key+'">'+items.map(([id,label])=>'<option value="'+id+'" '+(rule[key]===id?'selected':'')+'>'+label+'</option>').join('')+'</select></label>';return '<div data-cf-visual>'+options('palette',[['traffic','Rojo · amarillo · verde'],['blue','Blanco · azul'],['redblue','Rojo · blanco · azul']])+options('iconSet',[['traffic','Semáforos'],['arrows','Flechas'],['flags','Banderas'],['rating','Estrellas']])+'<label>Color de barras<input type="color" data-cf="barColor" value="'+esc(rule.barColor||'#77b3d5')+'"></label>'+options('barFill',[['solid','Sólido'],['gradient','Degradado']])+'</div>';}

